// Avisa SOLO si hay algo que contar: mensajes enviados, envios fallidos, demos que terminaron, o
// un barrido que no pudo mirar la base. Un 'cero' limpio NO manda nada: una alerta diaria que no
// dice nada se ignora en una semana.
const NL = String.fromCharCode(10);
const leer = (nombre) => {
  try {
    const raw = String($(nombre).first().json.stdout || '').trim();
    const linea = raw.split(NL).filter((l) => l.trim().startsWith('{')).pop();
    return linea ? JSON.parse(linea) : null;
  } catch (e) { return null; }
};
const partes = [];
let avisar = false;
const barridos = [['Seguimiento', leer('Barrer seguimiento')], ['Recordatorio', leer('Barrer recordatorio')], ['Demos terminadas', leer('Cerrar demos pasadas')]];
for (const par of barridos) {
  const etiqueta = par[0];
  const res = par[1];
  if (!res) { partes.push(etiqueta + ': NO se pudo leer el resultado del barrido (revisar el script en el VPS)'); avisar = true; continue; }
  if (res.ok === false) { partes.push(etiqueta + ': FALLO - ' + String(res.error || 'sin detalle')); avisar = true; continue; }
  const send = Array.isArray(res.send) ? res.send : [];
  const warns = Array.isArray(res.warnings) ? res.warnings : [];
  if (etiqueta === 'Demos terminadas') {
    // Este barrido no entrega mensajes: cada item es una demo que hay que cerrar a mano. El texto
    // completo con las tres opciones lo manda el propio efecto notify_sergio del barrido.
    if (send.length) { partes.push(etiqueta + ': ' + send.length + ' demo(s) esperando que digas como salio'); avisar = true; }
  } else {
    const enviados = send.filter((s) => s.deliveryStatus === 'sent');
    const fallidos = send.filter((s) => s.deliveryStatus === 'failed');
    const pagos = send.filter((s) => s.sendKind === 'plantilla');
    if (enviados.length) { partes.push(etiqueta + ': ' + enviados.length + ' mensaje(s) ENVIADO(s)' + (pagos.length ? ' (' + pagos.length + ' por plantilla PAGA)' : '')); avisar = true; }
    if (fallidos.length) { partes.push(etiqueta + ': ' + fallidos.length + ' NO salieron (la reserva ya se gasto: no se reintenta, para no mandar dos)'); avisar = true; }
  }
  if (warns.length) { partes.push(etiqueta + ' - avisos: ' + warns.join(' | ').slice(0, 300)); avisar = true; }
}
const text = ('Chatbot - barridos' + NL + NL + partes.join(NL)).slice(0, 3900);
return [{ json: { avisar: avisar, text: text } }];
